def transform(grid):
    n = len(grid[0])
    c = next(j for j, value in enumerate(grid[0]) if value == 2)
    out = [[0] * n for _ in range(n)]

    for r in range(n):
        if r <= c:
            out[r][c - r] = 2
            out[r][c + r] = 2

        for col in range(n):
            if abs(col - c) <= r - 2 and (col - r - c) % 4 == 0:
                out[r][col] = 1

    return out
